  const permissionFor = { dashboard:'dashboard.view', content:'content.view', users:'users.view', statistics:'dashboard.view', 'admin-ai':'content.view', messages:'messages.view', 'internal-messages':'messages.view', attachments:'messages.view', files:'media.view', navigation:'settings.view', settings:'settings.view', security:'security.manage', activity:'audit.view' };
