    for(const day of days){const col=make('div','chart-day');const value=make('em','',number(day.value));const bar=make('b');bar.style.height=`${Math.max(3,Math.round(day.value/max*100))}%`;bar.title=`${day.label}: ${day.value}`;const label=make('small','',day.label);col.append(value,bar,label);container.append(col);}
