    $('#statistics-summary').replaceChildren(...cards.slice(0,4).map(([label,value,note])=>{const card=make('article','stat-card');card.append(make('span','',label),make('strong','',value===undefined?'—':numberOrString(value)),make('small','',note));return card;}));
    chartBars($('#dashboard-visits'),summary?.visits); chartBars($('#dashboard-registrations'),summary?.registrations);
