  async function saveContent(event){event.preventDefault();if(!can('content.manage'))return;const id=$('#content-id').value;const payload=readContentForm();try{await api(id?`/api/admin/content/${encodeURIComponent(id)}`:'/api/admin/content',{method:id?'PUT':'POST',body:JSON.stringify(payload)});toast('تم حفظ المحتوى.');$('#content-form').reset();$('#content-editor').hidden=true;state.contentOffset=0;await loadContent();if(state.current==='dashboard')await loadSummary();}catch(error){toast(error.message);}}
