  function setupAttachments(){if(!can('messages.view'))return;$('#attachments-search').addEventListener('input',()=>{state.attachmentsOffset=0;loadAttachmentLibrary();});$('#attachments-type').addEventListener('change',()=>{state.attachmentsOffset=0;loadAttachmentLibrary();});$('#attachments-refresh').addEventListener('click',loadAttachmentLibrary);$('#attachments-prev').addEventListener('click',()=>{state.attachmentsOffset=Math.max(0,state.attachmentsOffset-40);loadAttachmentLibrary();});$('#attachments-next').addEventListener('click',()=>{state.attachmentsOffset+=40;loadAttachmentLibrary();});}
  function addInternalFiles(files){for(const file of files){if(state.internalFiles.length<3&&!state.internalFiles.some(item=>item.name===file.name&&item.size===file.size))state.internalFiles.push(file);}renderInternalFiles();}
  function setupInternalMessages(){if(!can('messages.view'))return;$('#internal-recipients-refresh').addEventListener('click',loadInternalMessages);$('#internal-messages-refresh').addEventListener('click',loadInternalMessageInbox);$('#internal-message-form').addEventListener('submit',sendInternalMessage);const input=$('#internal-message-files'),dropzone=$('#internal-message-dropzone');input.addEventListener('change',event=>{addInternalFiles([...event.target.files]);event.target.value='';});dropzone.addEventListener('click',()=>input.click());dropzone.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' ')input.click();});for(const type of ['dragenter','dragover'])dropzone.addEventListener(type,event=>{event.preventDefault();dropzone.classList.add('dragover');});for(const type of ['dragleave','drop'])dropzone.addEventListener(type,event=>{event.preventDefault();dropzone.classList.remove('dragover');});dropzone.addEventListener('drop',event=>addInternalFiles([...event.dataTransfer.files]));loadInternalMessages();}
  function setupMessages(){if(!can('messages.view'))return;$('#messages-search').addEventListener('input',()=>loadMessages());$('#messages-type').addEventListener('change',loadMessages);$('#messages-status').addEventListener('change',loadMessages);$('#messages-read').addEventListener('change',loadMessages);$('#messages-trash-toggle').addEventListener('change',loadMessages);$('#messages-refresh').addEventListener('click',loadMessages);}
  async function prepareFile(file){if(!file.type.startsWith('image/')||file.type==='image/gif'||!window.createImageBitmap)return file;try{const bitmap=await createImageBitmap(file);const scale=Math.min(1,2000/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.84));if(blob?.type==='image/webp'&&blob.size<file.size)return new File([blob],file.name.replace(/\.[^.]+$/,'')+'.webp',{type:'image/webp',lastModified:Date.now()});}catch{}return file;}
  async function uploadFiles(files){if(!can('media.manage'))return;const input=$('#file-input');input.disabled=true;for(const original of files){try{const file=await prepareFile(original);const signed=await api('/api/admin/files/presign',{method:'POST',body:JSON.stringify({name:file.name,type:file.type||'application/octet-stream',size:file.size})});const upload=await fetch('/api/storage/upload',{method:'PUT',headers:{'Content-Type':file.type||'application/octet-stream','X-CSRF-Token':state.csrf,'X-Upload-Key':signed.key},body:file});if(!upload.ok)throw new Error('تعذر رفع الملف إلى التخزين الدائم.');await api('/api/admin/files',{method:'POST',body:JSON.stringify({name:file.name,key:signed.key,type:file.type,size:file.size})});toast(`تم رفع ${file.name}.`);}catch(error){toast(error.message);}}input.value='';input.disabled=false;loadFiles();}
  async function loadFiles(){const params=new URLSearchParams({limit:'40',offset:'0',search:$('#files-search').value.trim()||state.search,trash:String($('#files-trash-toggle').checked)});try{const data=await api(`/api/admin/files?${params}`);state.files=data.items||[];renderFiles();}catch(error){$('#files-list').replaceChildren(empty(error.message));}}
  function downloadMedia(file){const link=make('a');link.href=file.url;link.download=file.original_name||'file';link.target='_blank';link.rel='noopener';document.body.append(link);link.click();link.remove();}
  function previewMedia(file){const body=make('div','attachment-preview-body');const type=String(file.content_type||'').toLowerCase();if(type.startsWith('image/')){const img=make('img');img.src=file.url;img.alt=file.original_name||'معاينة الملف';body.append(img);}else if(type==='application/pdf'){const frame=make('iframe');frame.src=file.url;frame.title=file.original_name||'معاينة PDF';body.append(frame);}else if(type.startsWith('video/')){const video=make('video');video.controls=true;video.src=file.url;video.style.width='100%';video.style.maxHeight='70vh';body.append(video);}else if(type.startsWith('audio/')){const audio=make('audio');audio.controls=true;audio.src=file.url;audio.style.width='100%';body.append(audio);}else if(type.startsWith('text/')||type==='application/json'){const frame=make('iframe');frame.src=file.url;frame.title=file.original_name||'معاينة الملف';body.append(frame);}else{body.append(make('p','',`المعاينة غير متاحة لهذا التنسيق (${file.content_type||'غير معروف'}).`));}body.append(btn('تنزيل الملف',()=>downloadMedia(file),'button primary'));openDialog(`معاينة: ${file.original_name||'ملف'}`,body);document.querySelector('.preview-dialog')?.classList.add('attachment-dialog');}
  function renderFiles(){const target=$('#files-list');if(!state.files.length){target.replaceChildren(empty('لا توجد ملفات في هذا العرض.'));return;}target.replaceChildren(...state.files.map(file=>{const card=make('article','media-card');if(file.content_type?.startsWith('image/')){const img=make('img');img.src=file.url;img.alt=file.original_name;img.loading='lazy';card.append(img);}else card.append(make('div','media-preview',file.content_type==='application/pdf'?'PDF':file.content_type?.startsWith('video/')?'فيديو':file.content_type?.startsWith('audio/')?'صوت':'ملف'));card.append(make('h3','',file.original_name),make('p','',`${file.content_type} · ${number(file.size_bytes)} بايت`));const actions=make('div','data-card-actions');if($('#files-trash-toggle').checked){if(can('media.manage'))actions.append(btn('استعادة',async()=>{try{await api(`/api/admin/files/${file.id}/restore`,{method:'POST',body:'{}'});loadFiles();}catch(error){toast(error.message);}},'button'),btn('حذف نهائي',()=>permanentlyDelete('files',file.id,loadFiles),'button danger'));}else{actions.append(btn('معاينة',()=>previewMedia(file),'button primary'),btn('تنزيل',()=>downloadMedia(file),'button'),btn('نسخ الرابط',async()=>{try{await navigator.clipboard.writeText(file.url);toast('تم نسخ رابط الملف.');}catch{toast(file.url);}},'button'));if(can('media.manage'))actions.append(btn('نقل للسلة',async()=>{try{const result=await api(`/api/admin/files/${file.id}`,{method:'DELETE',body:'{}'});toast(result.note||'أُخفي الملف من فهرس الموقع.');loadFiles();}catch(error){toast(error.message);}},'button'));}card.append(actions);return card;}));}
  function setupFiles(){if(!can('media.view'))return;$('#file-input').hidden=!can('media.manage');$('label[for="file-input"]').hidden=!can('media.manage');$('#file-input').addEventListener('change',event=>{if(event.target.files?.length)uploadFiles([...event.target.files]);});$('#files-search').addEventListener('input',loadFiles);$('#files-trash-toggle').addEventListener('change',loadFiles);$('#files-refresh').addEventListener('click',loadFiles);}
  async function loadNavigation(){try{const params=$('#navigation-trash-toggle').checked?'?trash=true':'';const data=await api(`/api/admin/navigation${params}`);state.navigation=data.items||[];renderNavigation();}catch(error){$('#navigation-list').replaceChildren(empty(error.message));}}
  function renderNavigation(){const target=$('#navigation-list');if(!state.navigation.length){target.replaceChildren(empty('لا توجد روابط في هذا العرض.'));return;}target.replaceChildren(...state.navigation.map(item=>{const card=make('article','data-card');const head=make('div','data-card-head'),info=make('div');info.append(make('h3','',item.label_ar),make('p','',`${item.href} · ${item.is_active?'ظاهر للزوار':'مخفي'} · الترتيب ${item.position}`));head.append(info);card.append(head);const actions=make('div','data-card-actions');if(item.deleted_at){actions.append(btn('استعادة',async()=>{try{await api(`/api/admin/navigation/${item.id}/restore`,{method:'POST',body:'{}'});loadNavigation();}catch(error){toast(error.message);}},'button'),btn('حذف نهائي',()=>permanentlyDelete('navigation',item.id,loadNavigation),'button danger'));}else{actions.append(btn('تعديل',()=>{ $('#navigation-id').value=item.id;$('#navigation-label-ar').value=item.label_ar;$('#navigation-label-en').value=item.label_en||'';$('#navigation-href').value=item.href;$('#navigation-position').value=item.position;$('#navigation-active').checked=item.is_active;window.scrollTo({top:0,behavior:'smooth'});},'button'));if(can('navigation.manage'))actions.append(btn('نقل للسلة',async()=>{try{await api(`/api/admin/navigation/${item.id}`,{method:'DELETE',body:'{}'});loadNavigation();}catch(error){toast(error.message);}},'button'));}card.append(actions);return card;}));}
  function setupNavigationForm(){if(!can('navigation.manage')){ $('#navigation-form').hidden=true;return;}$('#navigation-form').addEventListener('submit',async event=>{event.preventDefault();const id=$('#navigation-id').value;const body={id:id?Number(id):null,label_ar:$('#navigation-label-ar').value.trim(),label_en:$('#navigation-label-en').value.trim(),href:$('#navigation-href').value.trim(),position:Number($('#navigation-position').value)||0,is_active:$('#navigation-active').checked};try{await api('/api/admin/navigation',{method:'POST',body:JSON.stringify(body)});$('#navigation-form').reset();$('#navigation-id').value='';$('#navigation-position').value='0';$('#navigation-active').checked=true;toast('تم حفظ الرابط.');loadNavigation();}catch(error){toast(error.message);}});$('#navigation-reset').addEventListener('click',()=>{ $('#navigation-form').reset();$('#navigation-id').value='';$('#navigation-position').value='0';$('#navigation-active').checked=true;});$('#navigation-trash-toggle').addEventListener('change',loadNavigation);}
  async function loadSettings(){try{const data=await api('/api/admin/settings');const s=data.settings||{};$('#setting-site-name').value=s.site_name||'قادر';$('#setting-logo-url').value=s.logo_url||'';$('#setting-contact-email').value=s.contact_email||'';$('#setting-seo-description').value=s.seo_description||'';const links=s.social_links||{};$('#social-x').value=links.x||'';$('#social-instagram').value=links.instagram||'';$('#social-youtube').value=links.youtube||'';$('#setting-maintenance').checked=s.maintenance_mode===true;$('#setting-maintenance-message').value=s.maintenance_message||'الموقع تحت الصيانة، سنعود قريبًا.';$('#setting-notification-templates').value=JSON.stringify(s.notification_templates||{},null,2);$('#settings-form').querySelectorAll('input,textarea,button').forEach(input=>{if(!['backup-download','export-csv'].includes(input.id))input.disabled=!can('settings.manage');});$('#backup-download').hidden=!can('backups.manage');$('#export-csv').hidden=!can('users.view');}catch(error){toast(error.message);}}
  function setupSettings(){if(can('settings.manage'))$('#settings-form').addEventListener('submit',async event=>{event.preventDefault();const links={};for(const [key,id] of [['x','social-x'],['instagram','social-instagram'],['youtube','social-youtube']]){const value=$(`#${id}`).value.trim();if(value)links[key]=value;}let notificationTemplates;try{notificationTemplates=JSON.parse($('#setting-notification-templates').value||'{}');if(!notificationTemplates||typeof notificationTemplates!=='object'||Array.isArray(notificationTemplates))throw new Error();}catch{toast('قوالب الإشعارات يجب أن تكون كائن JSON صالحًا.');return;}const settings={site_name:$('#setting-site-name').value.trim(),logo_url:$('#setting-logo-url').value.trim(),contact_email:$('#setting-contact-email').value.trim(),seo_description:$('#setting-seo-description').value.trim(),social_links:links,maintenance_mode:$('#setting-maintenance').checked,maintenance_message:$('#setting-maintenance-message').value.trim(),notification_templates:notificationTemplates};try{await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({settings})});toast('تم حفظ إعدادات قادر.');}catch(error){toast(error.message);}});
    $('#backup-download').addEventListener('click',async()=>{try{const response=await fetch('/api/admin/backup',{credentials:'same-origin',cache:'no-store'});if(!response.ok)throw new Error('لا تملك إذن النسخ الاحتياطي أو تعذر إنشاؤه.');const blob=await response.blob();downloadBlob(blob,`qadir-backup-${new Date().toISOString().slice(0,10)}.json`);}catch(error){toast(error.message);}});
    $('#export-csv').addEventListener('click',exportUsersCsv);
  }
  function csvCell(value){let text=safeText(value);if(/^[=+\-@\t\r]/.test(text))text=`'${text}`;return `"${text.replace(/"/g,'""')}"`;}
  function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=make('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  async function exportContentCsv(){if(!can('content.view'))return;try{const rows=[];for(let offset=0;offset<100000;offset+=100){const data=await api(`/api/admin/content?limit=100&offset=${offset}&trash=false`);rows.push(...(data.items||[]));if(rows.length>=data.total||!(data.items||[]).length)break;}const columns=['kind','slug','title_ar','title_en','body_ar','body_en','category','tags','status','cover_url','publish_at','seo_title_ar','seo_title_en','seo_description_ar','seo_description_en'];const values=rows.map(item=>[item.kind,item.slug,item.title_ar,item.title_en,item.body_ar,item.body_en,item.category,Array.isArray(item.tags)?item.tags.join('|'):'',item.status,item.cover_url,item.publish_at,item.seo_title_ar,item.seo_title_en,item.seo_description_ar,item.seo_description_en]);const csv='\ufeff'+[columns,...values].map(row=>row.map(csvCell).join(',')).join('\r\n');downloadBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),'qadir-content.csv');}catch(error){toast(error.message);}}
  async function importContentCsv(event){const input=event.target;const file=input.files?.[0];if(!file)return;if(file.size<1||file.size>1024*1024){toast('حجم ملف CSV يجب ألا يتجاوز 1 ميغابايت.');input.value='';return;}try{const csv=await file.text();if(!confirm(`استيراد ملف ${file.name}؟ يتحقق الخادم من الملف ويضيف جميع صفوفه أو لا يضيف أيًا منها.`))return;const result=await api('/api/admin/content/import',{method:'POST',body:JSON.stringify({csv})});toast(`تم استيراد ${number(result.imported)} عنصرًا.`);state.contentOffset=0;await loadContent();await loadSummary();}catch(error){toast(error.message);}finally{input.value='';}}
  async function exportUsersCsv(){if(!can('users.view'))return;try{const rows=[];for(let offset=0;offset<100000;offset+=100){const data=await api(`/api/admin/users?limit=100&offset=${offset}`);rows.push(...(data.users||[]));if(rows.length>=data.total||!(data.users||[]).length)break;}const csv='\ufeff'+[['اسم المستخدم','الرتبة','الحالة','وقت النشاط بالثواني','تاريخ التسجيل','آخر نشاط'],...rows.map(user=>[user.username,user.roleLabel,user.isActive?'مفعّل':'موقوف',user.activeSeconds,user.createdAt,user.lastActiveAt])].map(row=>row.map(csvCell).join(',')).join('\r\n');downloadBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),'qadir-users.csv');}catch(error){toast(error.message);}}
  function setupSettingsForm(){if(!can('settings.view'))return;setupSettings();}
  async function loadActivity(){const query=$('#activity-search').value.trim()||state.search;const params=new URLSearchParams({search:query,limit:'100',offset:'0'});try{const data=await api(`/api/admin/activity?${params}`);const target=$('#activity-list');const items=data.items||[];target.replaceChildren(...(items.length?items.map(item=>{const card=make('article','data-card');card.append(make('h3','',`${item.actor_username} · ${item.action}`),make('p','',`${item.target_type}${item.target_id?` #${item.target_id}`:''} · ${dateText(item.created_at)}`));if(item.details&&Object.keys(item.details).length)card.append(make('p','',JSON.stringify(item.details)));return card;}):[empty('لا توجد أحداث مسجلة.')]));}catch(error){$('#activity-list').replaceChildren(empty(error.message));}}
  async function loadSessions(){try{const data=await api('/api/admin/security/sessions');state.sessions=data.items||[];const target=$('#sessions-list');if(!state.sessions.length){target.replaceChildren(empty('لا توجد جلسات نشطة.'));return;}target.replaceChildren(...state.sessions.map(session=>{const card=make('article','data-card');card.append(make('h3','',session.user_agent||'جهاز غير معروف'),make('p','',`آخر نشاط: ${dateText(session.last_seen_at)} · انتهاء: ${dateText(session.expires_at)}`));const hash=session.ip_fingerprint?make('p','',`بصمة عنوان مختصرة: ${session.ip_fingerprint}`):null;if(hash)card.append(hash);card.append(btn('إنهاء الجلسة',async()=>{try{await api(`/api/admin/security/sessions/${session.id}`,{method:'DELETE',body:'{}'});toast('تم إنهاء الجلسة.');loadSessions();}catch(error){toast(error.message);}},'button'));return card;}));}catch(error){$('#sessions-list').replaceChildren(empty(error.message));}}
  function setupActivitySecurity(){if(can('audit.view')){$('#activity-search').addEventListener('input',()=>loadActivity());$('#activity-refresh').addEventListener('click',loadActivity);}if(can('security.manage'))$('#sessions-refresh').addEventListener('click',loadSessions);}
  function setup(){setupNavigation();setupContent();setupSiteLessons();setupAdminAi();setupMessages();setupInternalMessages();setupAttachments();setupFiles();setupNavigationForm();setupSettingsForm();setupActivitySecurity();const allNav= $('#admin-nav');allNav.addEventListener('click',event=>{const button=event.target.closest('[data-section]');if(button&&button.dataset.section==='users'&&can('users.view')){const input=$('#account-search');if(input&&!input.closest('.field-wrap').hidden){input.value='';input.dispatchEvent(new Event('input',{bubbles:true}));}}});$('#backup-download').hidden=!can('backups.manage');$('#export-csv').hidden=!can('users.view');state.summaryTimer=setInterval(()=>{if(document.visibilityState==='visible')loadSummary();},60000);}
  window.addEventListener('qadir-admin-authenticated',event=>{if(state.user)return;state.user=event.detail.user;state.csrf=event.detail.csrfToken||'';$('#admin-identity').textContent=`${state.user.username} · ${state.user.roleLabel||'إدارة'}`;$('#workspace-user').textContent=state.user.username;setup();},{once:true});
